def url(lang,slug=''):
    return f'/{lang}/'+(slug+'/' if slug else '')

def render(lang='en', slug='', automatic=False):
    c=COPY[lang];i=SLUGS.index(slug);title=c['titles'][i];description=c['descriptions'][i];canonical=BASE+url(lang,slug)
    alternates=''.join(f'<link rel="alternate" hreflang="{l}" href="{BASE+url(l,slug)}">' for l in COPY)+f'<link rel="alternate" hreflang="x-default" href="{BASE+url("en",slug)}">'
    schema={'@context':'https://schema.org','@graph':[{'@type':'Organization','@id':BASE+'/#organization','name':'NeuroHelen','url':BASE,'logo':BASE+'/favicon-48.png','email':'support@neurohelen.com'},{'@type':'WebSite','@id':BASE+'/#website','name':'NeuroHelen Studio','url':BASE,'publisher':{'@id':BASE+'/#organization'}},{'@type':'SoftwareApplication','name':'NeuroHelen Studio','url':canonical,'applicationCategory':'MultimediaApplication','operatingSystem':'Web browser','description':description,'publisher':{'@id':BASE+'/#organization'},'offers':{'@type':'Offer','price':package_usd(PACKAGES[0][0],PACKAGES[0][3]),'priceCurrency':'USD','description':f"{PACKAGES[0][2]} {c['tokens']}"}}]}
    nav=''.join(f'<a href="#{a}">{esc(t)}</a>' for a,t in zip(['explore','styles','pricing','faq'],c['nav']))
    languages=''.join(f'<a data-language="{l}" href="{url(l,slug)}" lang="{l}" aria-label="{name}"'+(' aria-current="page"' if l==lang else '')+f'>{short}</a>' for l,short,name in [('ru','RU','Русский'),('uk','UA','Українська'),('en','EN','English')])
    tasks=''.join(f'<a class="task" href="{url(lang,s)}"><span class="number">0{n}</span><h3>{esc(c["tasks"][n])}</h3><p>{esc(c["tasktext"][n-1])}</p><span aria-hidden="true">↗</span></a>' for n,s in enumerate(SLUGS[1:],1))
    steps=''.join(f'<article><span class="number">0{n+1}</span><h3>{esc(t)}</h3><p>{esc(c["steptext"][n])}</p></article>' for n,t in enumerate(c['steps']))
    styles=''.join(f'<figure><img src="/style-{s}.jpg" alt="{esc(t)}" width="480" height="480" loading="lazy"><figcaption>{esc(t)}</figcaption></figure>' for s,t in zip(['3d','anime','2d','clay','watercolor'],c['style_names']))
    pricing=''.join(f'<article class="price"><h3>{esc(c["packages"][n])}</h3><p class="amount">${package_usd(key,rub)} <small>— {number(rub)} ₽</small></p><p>{number(tokens)} {c["tokens"]}</p><a class="button light" data-enter href="/studio">{c["cta"]} ↗</a></article>' for n,(key,_,tokens,rub) in enumerate(PACKAGES))
    faq=''.join(f'<details><summary>{esc(q)}</summary><p>{esc(a)}</p></details>' for q,a in zip(c['questions'],c['answers']))
    gallery=''
    if slug in SLUGS:
        heading={'ru':'Истории, которые уже ожили','en':'Stories brought to life','uk':'Історії, що вже ожили'}[lang]
        note={'ru':'Посмотрите примеры мультфильмов. Звук можно включить в плеере.','en':'Watch example cartoons. You can turn sound on in the player.','uk':'Перегляньте приклади мультфільмів. Звук можна ввімкнути в плеєрі.'}[lang]
        names={'ru':['Приключения котёнка','Кот-будильник','История в салоне','Кот на кухне','История об уходе за кожей','Косметика оживает','Робот и ожившие герои'],'en':['A kitten’s adventures','The alarm-clock cat','A salon story','A cat in the kitchen','A skincare story','Skincare comes to life','A robot and characters brought to life'],'uk':['Пригоди кошеняти','Кіт-будильник','Історія в салоні','Кіт на кухні','Історія про догляд за шкірою','Косметика оживає','Робот і ожилі герої']}[lang]
        ids=[2,3,6,1] if not slug else [1,3] if slug=='script' else [5,6] if slug=='products' else [2,4,7]
        gallery='<section id="examples"><h2>'+heading+'</h2><p>'+note+'</p><div class="video-examples">'+''.join(f'<figure><video controls playsinline muted preload="none" poster="/examples/poster-{n}.jpg" width="540" height="960" aria-label="{esc(names[n-1])}"><source src="/examples/video-{n}.mp4" type="video/mp4"></video><figcaption>{esc(names[n-1])}</figcaption></figure>' for n in ids)+'</div></section>'
    detail=''
    if i:
        d=DETAILS[lang][i-1]
        detail='<section><h2>'+esc(d[0])+'</h2><div class="steps">'+''.join('<article><p>'+esc(t)+'</p></article>' for t in d[1:])+'</div></section>'
    schema_json=json.dumps(schema,ensure_ascii=False).replace('<',chr(92)+'u003c')
    return f'''<!doctype html><html lang="{lang}" data-auto-language="{str(automatic).lower()}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(title)} — NeuroHelen Studio</title><meta name="description" content="{esc(description)}"><link rel="canonical" href="{canonical}">{alternates}<meta property="og:type" content="website"><meta property="og:title" content="{esc(title)} — NeuroHelen Studio"><meta property="og:description" content="{esc(description)}"><meta property="og:url" content="{canonical}"><meta property="og:image" content="{BASE}/hero.png"><meta name="twitter:card" content="summary_large_image"><meta name="google-site-verification" content="K6e9iyKqvSDdzaHeNlEIUMpTFtGZrebre6yNUIKOZMs"><meta name="yandex-verification" content="178ba4fec78bbadc"><link rel="icon" href="/favicon.ico"><link rel="apple-touch-icon" href="/apple-touch-icon.png"><link rel="stylesheet" href="/landing.css?v=1"><script src="/landing.js?v=1" defer></script><script type="application/ld+json">{schema_json}</script></head><body><header><a class="brand" href="{url(lang)}"><span>✳</span> neurohelen<small>STUDIO</small></a><nav>{nav}</nav><div class="header-actions"><div class="languages">{languages}</div><a class="login" data-enter href="/studio">{c['login']} ↗</a></div></header><main><section class="hero"><div><p class="eyebrow">{c['eyebrow']}</p><h1>{esc(title)}</h1><p class="lead">{esc(description)}</p><a class="button" data-enter href="/studio">{c['cta']} ↗</a></div><div class="hero-picture"><img src="/hero.png" alt="{esc(c['style_names'][0])}" width="1024" height="1024" fetchpriority="high"><span class="sticker">{c['style_names'][0]}</span></div></section>{gallery}<section id="explore"><p class="eyebrow">NEUROHELEN STUDIO</p><h2>{c['tasks'][0]}</h2><div class="tasks">{tasks}</div></section>{detail}<section class="idea"><span class="spark" aria-hidden="true">✦</span><div><h2>{c['example']}</h2><p class="lead">{esc(c['examples'][i])}</p><small>{c['example_note']}</small></div></section><section><h2>{c['steps_title']}</h2><div class="steps">{steps}</div></section><section id="styles"><h2>{c['styles']}</h2><p>{c['style_note']}</p><div class="styles">{styles}</div></section><section class="models"><h2>{c['models']}</h2><p class="lead">{c['model_note']}</p></section><section id="pricing"><h2>{c['prices']}</h2><p>{c['price_note']}</p><div class="prices">{pricing}</div></section><section id="faq"><h2>{c['faq']}</h2>{faq}</section><section class="final"><h2>{c['final']}</h2><a class="button" data-enter href="/studio">{c['cta']} ↗</a></section></main><footer><a class="brand" href="{url(lang)}">✳ neurohelen</a><div><strong>{c['support']}</strong><p><a href="mailto:support@neurohelen.com">support@neurohelen.com</a></p><small>{c['hours']}</small></div></footer></body></html>'''

